-- Jeu source transposé en SQLite (mode démonstration).
DROP TABLE IF EXISTS paiement;
DROP TABLE IF EXISTS location;
DROP TABLE IF EXISTS abonne;
-- Base transactionnelle de test (source fournie par la DSI).
-- Contient des données à caractère personnel : elle n'est jamais copiée
-- telle quelle dans le socle analytique (cf. docs/04-rgpd...).
CREATE TABLE abonne (
    id_abonne      INTEGER PRIMARY KEY,
    nom            TEXT NOT NULL,
    prenom         TEXT NOT NULL,
    email          TEXT NOT NULL,
    telephone      text,
    date_naissance date,
    ville          text,
    type_abonnement TEXT NOT NULL,
    date_adhesion  TEXT NOT NULL
);
CREATE TABLE location (
    id_location       INTEGER PRIMARY KEY,
    id_abonne         INTEGER NOT NULL REFERENCES abonne(id_abonne),
    id_vehicule       TEXT NOT NULL,
    id_station_depart text,
    id_station_arrivee text,
    debut             TEXT NOT NULL,
    fin               TEXT,
    distance_km       REAL
);
CREATE TABLE paiement (
    id_paiement  INTEGER PRIMARY KEY,
    id_location  INTEGER NOT NULL REFERENCES location(id_location),
    montant_eur  REAL NOT NULL,
    moyen        TEXT NOT NULL,
    date_paiement TEXT NOT NULL
);
CREATE INDEX idx_location_debut ON location(debut);
CREATE INDEX idx_location_abonne ON location(id_abonne);
CREATE INDEX idx_paiement_location ON paiement(id_location);
